onChange.script:

if currentValue.value is None: return
if self.custom.table.columns.numCols > (currentValue.value.getColumnCount() - self.custom.table.columns.fixedColLength) and currentValue.value.getColumnCount() >  20:
	self.custom.table.columns.numCols = currentValue.value.getColumnCount() - self.custom.table.columns.fixedColLength

transforms.code:
if len(value.data) > 1:
	rows = self.custom.selection.rows
	cols = self.custom.selection.cols
	rows.append(value.selectedRow)
	cols.append(value.selectedColumn)
else:
	rows = []
	cols = []

return {'rows': list(set(rows)), 'cols': list(set(cols))}

customMethods.script:
system.perspective.print("getData() called")

filters = self.view.params.value.filters
if filters.masterChkShtId is None: return system.dataset.toDataSet([],[])

system.perspective.print("getData() called")
chkStates = system.kanoa.utilities.convertDatasetToDict(system.kanoa.quality.sheet.getStates({'enabled': True}), 'chkShtStateName', 'chkShtStateId')
self.view.params.infoBar = {"showBar": True, "text": "Getting data...", "type": "INFO"}

chkShtEventInfo = dict(filters)	
if chkShtEventInfo.has_key('assetPath') and chkShtEventInfo['assetPath'] is not None: chkShtEventInfo['assetPath'] = chkShtEventInfo['assetPath'] + '%'

if chkShtEventInfo.has_key('itemClasses') and len(chkShtEventInfo['itemClasses']) > 0: chkShtEventInfo['itemClassPath'] = chkShtEventInfo['itemClasses'][0]['itemClassPath'] +'%'
if chkShtEventInfo.has_key('items') and len(chkShtEventInfo['items']) > 0: chkShtEventInfo['itemId'] = chkShtEventInfo['items'][0]['itemId']

chkShtEventInfo['chkShtStateIds'] = [chkStates['Approved']]

if chkShtEventInfo.has_key('items') and len(chkShtEventInfo['items']) > 0: chkShtEventInfo['itemId'] = chkShtEventInfo['items'][0]['itemId']	
if chkShtEventInfo.has_key('itemClasses'): chkShtEventInfo.pop('itemClasses')
if chkShtEventInfo.has_key('items'): chkShtEventInfo.pop('items')	
if chkShtEventInfo.has_key('chkStates'): chkShtEventInfo.pop('chkStates')

data, msg = system.kanoa.quality.analysis.getChkItemEventsByColumn(chkShtEventInfo)

self.view.params.infoBar = {"showBar": False, "text": "", "type": "INFO"}
if data.rowCount == 0: system.perspective.sendMessage('showWarningToast', {'message': 'No checks found'})
return data
